package com.bank.median;

import java.util.Collections;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Tracks the running median of a transaction-amount stream with two heaps.
public class RunningMedian {

    private static final Logger log = Logger.getLogger(RunningMedian.class.getName());

    // lower half: max-heap (largest low on top)
    private final PriorityQueue<Long> low = new PriorityQueue<>(Collections.reverseOrder());
    // upper half: min-heap (smallest high on top)
    private final PriorityQueue<Long> high = new PriorityQueue<>();

    public void add(long amount) {
        low.offer(amount);            // step 1: into lower half
        high.offer(low.poll());       // step 2: shift boundary up to upper half
        if (high.size() > low.size()) {
            low.offer(high.poll());   // step 3: keep low >= high in size
        }
        log.info("Added " + amount + " -> median=" + median());
    }

    public double median() {
        if (low.size() > high.size()) {
            return low.peek();                        // odd count
        }
        return (low.peek() + high.peek()) / 2.0;      // even count
    }
}
