package com.bank.median;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MedianDemo {

    private static final Logger log = Logger.getLogger(MedianDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Running Median of Transaction Amounts");
        RunningMedian rm = new RunningMedian();
        long[] stream = {5000, 3000, 8000, 1000, 10000};
        for (long amt : stream) {
            rm.add(amt);
        }
    }
}
